  pairs.push(...await page.getByRole('heading',{name:'Feedback',exact:true,level:2}).evaluate(el=>{function color(value,background){const c=document.createElement('canvas').getContext('2d');if(background){c.fillStyle=background;c.fillRect(0,0,1,1);}c.fillStyle=value;c.fillRect(0,0,1,1);return [...c.getImageData(0,0,1,1).data].slice(0,3);}function luminance(rgb){return rgb.map(v=>{v/=255;return v<=.04045?v/12.92:((v+.055)/1.055)**2.4;}).reduce((n,v,i)=>n+v*[.2126,.7152,.0722][i],0);}const targets=[el,document.querySelector('input[aria-label="Search feedback"]'),...document.querySelectorAll('[role="tab"]')];return targets.map(node=>{const fg=getComputedStyle(node).color;let p=node;let bg='';while(p){const candidate=getComputedStyle(p).backgroundColor;if(candidate!=='rgba(0, 0, 0, 0)'&&candidate!=='transparent'){bg=candidate;break;}p=p.parentElement;}const a=luminance(color(fg,bg)),b=luminance(color(bg));return {text:node.textContent||node.getAttribute('aria-label'),fgRgb:color(fg,bg),bgRgb:color(bg),ratio:(Math.max(a,b)+.05)/(Math.min(a,b)+.05),fg,bg};});}));
